CREATE OR REPLACE TABLE KFL_PRODUCTION_CLONE_GCP_MIGRATION_20260608_0800.DBP_DATA.WBS_WERBEAENDERUNGEN_1 (
	MANDANT_ID NUMBER(38,0) NOT NULL COMMENT 'Mandant_1 im DWH.',
	AKTION_ID VARCHAR(10) NOT NULL COLLATE 'en-ci' COMMENT 'Aktion_1-ID.',
	OFFER_ID NUMBER(38,0) NOT NULL COMMENT 'Offer / Angebot_1-ID',
	WUP_ID NUMBER(38,0) NOT NULL COMMENT 'Filialnummer.',
	ART_ID NUMBER(38,0) NOT NULL COMMENT 'Input: Artikel_1-ID einschließlich der Generationen-ID (9-stellig); Output: 7-stellige L&S-ID + Counter = 8-stellige Artikel_1-ID. WWNNNNPC (Warengruppe, Nummer, Prüfziffer, Counter) Regel: Neuer Artikel_1 -> Counter +1.',
	DAT_BELADUNG DATE NOT NULL COMMENT 'Technisches Beladungsdatum.',
	MANDANT_ID_VZ NUMBER(38,0) NOT NULL COMMENT 'Mandant_1 VZ.',
	WUP_ID_VZ NUMBER(38,0) NOT NULL DEFAULT -1 COMMENT 'Verteilzentrumsnummer / VZ-WUP_1-ID.',
	NB_ID NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Im bisherigen System die 4 Stelle der Marktnummer die Nebenbetriebskennziffer.',
	NB_ID_VZ NUMBER(38,0) NOT NULL DEFAULT -111 COMMENT 'Nebenbetriebskennziffer VZ',
	DAT_AB DATE COMMENT 'Aktion_1 gültig von.',
	DAT_BIS DATE COMMENT 'Aktion_1 gültig bis.',
	KJWO NUMBER(38,0) COMMENT 'Werbekalenderwoche, JJJJWW.',
	AUSLIEFERGRUPPE_ID VARCHAR(10) COLLATE 'en-ci' COMMENT 'Ausliefergruppe / Auslieferungsgruppe.',
	WBS_PHASE_ID NUMBER(38,0) COMMENT 'WBS-Phase. Gibt an, in welcher Phase bzw. in welchem Prozess-Schritt des Werbemengenberechnungsprozesses sich der Artikel_1 befindet.',
	GP_ID NUMBER(38,0) COMMENT 'Lieferant-ID.',
	GK_FG NUMBER(38,0) COMMENT 'Flag: Gondelkopf',
	FACHBODEN_FG NUMBER(38,0) COMMENT 'Flag: Fachboden',
	TITEL_FG NUMBER(38,0) COMMENT 'Flag: Titelseite',
	RUECKSEITE_FG NUMBER(38,0) COMMENT 'Flag: Rückseite',
	ERSTE_SEITE_FG NUMBER(38,0) COMMENT 'Flag: Erste Seite',
	KASSE_FG NUMBER(38,0) COMMENT 'Flag: Kassenbereich',
	TV_FG NUMBER(38,0) COMMENT 'Flag: TV-Werbung',
	NEUER_ARTIKEL_FG NUMBER(38,0) COMMENT 'Flag: Neuer Artikel_1',
	PREIS_NORMAL NUMBER(9,2) COMMENT 'Normal-Verkaufspreis (Brutto).',
	PREIS_AKTION NUMBER(9,2) COMMENT 'Aktions-Verkaufspreis (Brutto).',
	ANZ_TAGE_WERBUNG NUMBER(38,0) COMMENT 'Anzahl Tage Werbung.',
	TAGE_BIS_BESTELLUNG_LIEFERANT NUMBER(38,0) COMMENT 'Anzahl Tage bis Lieferantenbestellung.',
	TAGE_BIS_DEADLINE_PRINT NUMBER(38,0) COMMENT 'Anzahl Tage bis Print-Deadline.',
	TAGE_BIS_INITIALE_BELIEFERUNG NUMBER(38,0) COMMENT 'Anzahl Tage bis zur initialen Belieferung.',
	ANZ_WERBEAENDERUNGEN_AUFG NUMBER(38,0) COMMENT 'Anzahl Werbeänderungen (aufg.)',
	ANZ_WERBEAENDERUNGEN_NACH_PRINT NUMBER(38,0) COMMENT 'Anzahl Werbeänderungen (nach Print).',
	WERBEAENDERUNG_ANGEBOTSPREISREDUKTION_FG NUMBER(38,0) COMMENT 'Flag: Aktions-Verkaufspreis Reduktion.',
	WERBEAENDERUNG_ANGEBOTSPREISERHOEHUNG_FG NUMBER(38,0) COMMENT 'Flag: Aktions-Verkaufspreis Erhöhung.',
	WERBEAENDERUNG_NORMALPREISREDUKTION_FG NUMBER(38,0) COMMENT 'Flag: Normal-Verkaufspreis Reduktion.',
	WERBEAENDERUNG_NORMALPREISERHOEHUNG_FG NUMBER(38,0) COMMENT 'Flag: Normal-Verkaufspreis Erhöhung.',
	WERBEAENDERUNG_ARTIKELNEUANLAGE_FG NUMBER(38,0) COMMENT 'Flag: Artikelneuanlage.',
	WERBEAENDERUNG_ARTIKELENTFERNUNG_FG NUMBER(38,0) COMMENT 'Flag: Artikelentfernung.',
	WERBEAENDERUNG_MARKTANZAHLERHOEHUNG_FG NUMBER(38,0) COMMENT 'Flag: Anz. Märkte Erhöhung.',
	WERBEAENDERUNG_MARKTANZAHLREDUKTION_FG NUMBER(38,0) COMMENT 'Flag: Anz. Märkte Reduktion.',
	WERBEAENDERUNG_ABBILDUNGSAENDERUNG_FG NUMBER(38,0) COMMENT 'Flag: Änderung Abbildung.',
	WERBEAENDERUNG_RADIO_TV_BILLBOARD_FG NUMBER(38,0) COMMENT 'Flag: Radio / TV / Billboard.',
	WERBEAENDERUNG_KOLLIINHALTSAENDERUNG_FG NUMBER(38,0) COMMENT 'Flag: Änderung Kolliinhalt.',
	WERBEAENDERUNG_WERBETHEMA_FG NUMBER(38,0) COMMENT 'Flag: Änderung Werbethema.',
	WERBEAENDERUNG_SONSTIGES_FG NUMBER(38,0) COMMENT 'Flag: Sonstige Änderung.',
	WERBEAENDERUNG_BONUSKAUF_PROMOTIONSTYP_FG NUMBER(38,0) COMMENT 'Flag: Änderung bonuskauf_promotionstyp.',
	MINDESTPLATZIERUNG_FG NUMBER(38,0) COMMENT 'Flag: Mindestplatzierung.',
	BEST_GENERIERT_FG NUMBER(38,0) COMMENT 'Flag: Bestellung generiert.',
	HOHE_MENGENAENDERUNG_FG NUMBER(38,0) COMMENT 'Flag: Mengenänderung > 20 %.',
	GERINGE_MENGENAENDERUNG_FG NUMBER(38,0) COMMENT 'Flag: Mengenänderung < 20 %.',
	GESTEUERTE_PROGNOSE_FG NUMBER(38,0) COMMENT 'Flag: Prognose durch User gesteuert (Mengen FCST <> FCST_UDF).',
	MENGE_MINDESTPLATZIERUNG_BME NUMBER(18,3) COMMENT 'Menge Mindestplatzierung in BME.',
	FIXMENGE_FG NUMBER(38,0) COMMENT 'Flag: Fixmenge.',
	FIXMENGE_BME NUMBER(18,3) COMMENT 'Fixmenge in BME.',
	MINDESTMENGE_FG NUMBER(38,0) COMMENT 'Flag: Mindestmenge.',
	MINDESTMENGE_BME NUMBER(18,3) COMMENT 'Mindestmenge in BME.',
	MAXIMALMENGE_FG NUMBER(38,0) COMMENT 'Flag: Maximalmenge.',
	MAXIMALMENGE_BME NUMBER(18,3) COMMENT 'Maximalmenge in BME.',
	BESTAND_WUP_BME NUMBER(18,3) COMMENT 'Marktbestand in BME.',
	OFFENE_BESTELLUNGEN_BME NUMBER(18,3) COMMENT 'Offene Bestellungen in BME.',
	ORDER_FORECAST_BME NUMBER(18,3) COMMENT 'Order Forecast in BME.',
	PROJIZIERTER_BESTAND_VOR_WERBUNG_BME NUMBER(18,3) COMMENT 'Projizierter Bestand vor Werbung in BME.',
	DURCHSCHNITTLICHER_ABVERKAUF_BME NUMBER(18,3) COMMENT 'Durchschnittlicher Abverkauf in BME.',
	PROGNOSE_WERBEZEITRAUM_BME NUMBER(18,3) COMMENT 'Prognose Werbezeitraum in BME.',
	ANTEIL_WUP_ARTIKEL_PERC NUMBER(9,2) COMMENT 'Anteil dieses Marktes an der Gesamt-Prognosemenge.',
	BEDARF_BME NUMBER(18,3) COMMENT 'Bedarf in Basismengeneinheit.',
	BEDARF_AME NUMBER(18,3) COMMENT 'Bedarf in Ausliefermengeneinheit.',
	BEDARF_PAL NUMBER(18,3) COMMENT 'Bedarf in Paletten.',
	ZIELBESTAND_BME NUMBER(18,3) COMMENT 'Zielbestand in Basismengeneinheit.',
	BESTELLMENGE_OHNE_BESTAND_AME NUMBER(38,3) COMMENT 'Errechnete Werbe-Bestellmenge ohne Bestandsberücksichtigung in Ausliefermengeneinheit (AME, z.B. Kolli oder KG). Ohne Bestandsberücksichtigung ist z.B. für den Fall, dass ein aktuell hoher Bestand vor der Aktion_1 wegen Mhd-Ablauf verfällt, oder es wegen anderer Aktionen zu erwarten ist, dass der Bestand sich abverkauft, weshalb die unreduzierte Bestellmenge genommen werden kann.',
	BESTELLMENGE_OHNE_BESTAND_PAL NUMBER(38,3) COMMENT 'Errechnete Werbe-Bestellmenge ohne Bestandsberücksichtigung in Paletten (PAL). Ohne Bestandsberücksichtigung ist z.B. für den Fall, dass ein aktuell hoher Bestand vor der Aktion_1 wegen Mhd-Ablauf verfällt, oder es wegen anderer Aktionen zu erwarten ist, dass der Bestand sich abverkauft, weshalb die unreduzierte Bestellmenge genommen  werden kann.',
	BESTELLMENGE_MIT_BESTAND_AME NUMBER(38,3) COMMENT 'Errechnete Werbe-Bestellmenge mit Bestandsberücksichtigung in Ausliefermengeneinheit (AME, z.B. Kolli oder KG). Mit Bestandsberücksichtigung ist z.B. für den Fall, dass es einen aktuell hohen Bestand des Artikels gibt, der vor der Aktion_1 wahrscheinlich nicht signifikant abnimmt, was eine_1 Reduktion der Bestellmenge zur Folge haben kann..',
	BESTELLMENGE_MIT_BESTAND_PAL NUMBER(38,3) COMMENT 'Errechnete Werbe-Bestellmenge mit Bestandsberücksichtigung in Paletten (PAL). Mit Bestandsberücksichtigung ist z.B. für den Fall, dass es einen aktuell hohen Bestand des Artikels gibt, der vor der Aktion_1 wahrscheinlich nicht signifikant abnimmt, was eine_1 Reduktion der Bestellmenge zur Folge haben kann.',
	AKTION_REIHENFOLGE_ZUKUNFT_NR NUMBER(38,0) COMMENT 'Gibt an, an wievielter Stelle die betrachtete Aktion_1 in der aktuellen Reihenfolge kommender Aktionen steht. Der Rang kann sich im Zeitverlauf ändern (z.B. durch entfallene oder hinzukommende Aktionen) und wird mit jeder dat_beladung neu ermittelt, Mögliche Werte können 1, 2, 3, etc. sein.',
	PREIS_NACHLASS_PERC NUMBER(9,2) COMMENT 'Preisnachlass in %.',
	KOLLIFAKTOR NUMBER(13,3) COMMENT 'Kollifaktor (Menge in BME pro Kolli).',
	MULTI_OFFER_ID_FG NUMBER(38,0) COMMENT 'Artikel_1 mit mehreren offer_ids / angebot_ids bzw. aktion_ids.',
	WERBEAENDERUNG_MENGE_VORLAUF NUMBER(18,3) COMMENT 'Mengenänderung zum Vorlauf.',
	FIXMENGE_WFL_FG NUMBER(38,0) COMMENT 'Fixmenge Flag vom Warenfluss.',
	FIXMENGE_WFL_BME NUMBER(18,3) COMMENT 'Fixmenge BME vom Warenfluss.',
	FIXMENGE_WFL_AENDERUNG_FG NUMBER(38,0) COMMENT 'Bezieht sich auf die Warenfluss FIXMenge Änderung , die in der Spalte FIXMENGE_WFL_BME stattfindet . Das Flag wird auf 1 gesetzt, wenn sich die vom Warenfluss gesetzte Fixmenge im Vergleich zum letzten Berechnungstag geändert hat.',
	FIXMENGE_WFL_VORTAG_BME NUMBER(38,3) COMMENT 'Diese Spaltesie ermöglicht dem Benutzer zu erfahren, welche Menge in BME der Warenfluss am Vortag hatte. Sie ist auch erforderlich, um die Änderung der Fixmenge WFL (Spalte: fixmenge_wfl_bme) nachzuvollziehen.',
	PREIS_NORMAL_VORLAUF NUMBER(9,2) COMMENT 'Normalpreis zum Vorlauf.',
	PREIS_AKTION_VORLAUF NUMBER(9,2) COMMENT 'Aktionspreis zum Vorlauf.',
	TOP_GK_FG NUMBER(38,0) COMMENT 'initiale Belieferung zur Identifizierung von Belegart UBGK zur Aussteuerung TOP Gondelkopfprozess.',
	BESTAND_VZ NUMBER(18,3) COMMENT 'Anzeige von VZ Bestand (Frei verfügbar).',
	BLOCKIERTER_BESTAND_VZ NUMBER(18,3) COMMENT 'Anzeige VZ Bestand (für Werbung blockiert).',
	FINAL_VERFUEGBARER_BESTAND_VZ NUMBER(18,3) COMMENT 'Anzeige Anteil (customizing) VZ Bestand (für Werbung blockiert)+Anzeige VZ Bestand (frei verfügbar)*Faktor.',
	BESTELLUNG_LIEFERANT_MENGE NUMBER(18,3) COMMENT 'Übertragung Richtung VZ-Disposchnittstelle.',
	BESTELLUNG_LIEFERANT_FG NUMBER(38,0) COMMENT 'Sagt aus ob die Bestellung beim Lieferanten an das VZ getätigt wurde. Die Flag BESTELLUNG_LIEFERANT_MIT_BESTAND_FG sagt dann aus wie bzw. welche Art_1 von Bestellung getätigt wurde. Wenn BESTELLUNG_LIEFERANT_FG = 1 und BESTELLUNG_LIEFERANT_MIT_BESTAND_FG = 0 ist dann wurde eine_1 Bestellung ohne Bestandsberücksichtigung getätigt.',
	BESTELLUNG_LIEFERANT_MIT_BESTAND_FG NUMBER(38,0) COMMENT 'Flag: Wird gesetzt, wenn die Werbemenge mit Bestandsberücksichtigung durch die VZ-Disposition beim Lieferanten bestellt werden soll (Phase-Switch I).\n            Wird für Artikellevel erst über Warengruppeneinstellungen in TS_WBS_WARENGRUPPE.AUTO_BESTELLMENGE_MIT_BESTAND_PHASE_SWITCH_I_FG gesteuert, kann dann aber auch manuell für den Artikel_1 in MSTR gesetzt bzw. überschrieben werden.\n            Mit der Flag soll auch verhindert werden, dass die initiale Liefermenge an die Märkte erneut mit Bestandsberücksichtigung ermittelt wird (Phase-Switch III), was einem doppelten Abzug entsprechen würde. Also für den Fall, dass ein MIT_BESTAND Phase-Switch auch auf 1 gestellt wird, während der andere schon auf 1 ist. (TS_WBS_WARENGRUPPE.AUTO_BESTELLMENGE_MIT_BESTAND_PHASE_SWITCH_I_FG und TS_WBS_WARENGRUPPE.AUTO_BESTELLMENGE_MIT_BESTAND_PHASE_SWITCH_III_FG sollten auch nicht gleichzeitig 1 sein.)',
	STILLE_AKTION_FG NUMBER(38,0) COMMENT 'Identifikation \""In Store Promotions\"" um Artikel_1 mit FG aus Berechnung auszuschließen.',
	PROGNOSE_UNGESTEUERT NUMBER(18,3) COMMENT 'Prognose ungesteuert aus UDF, ohne Korrekturen / strukturierte Artikel.',
	MENGE_ZULETZT_DC_PROMO NUMBER(18,3) COMMENT 'Menge die zuletzt aus DC Promo übertragen wurde.',
	PMR_WERBETHEMA_ID VARCHAR(6) COLLATE 'en-ci' COMMENT 'Thema ID.',
	REFERENZMARKT_FALLBACK_FG NUMBER(38,0) COMMENT 'Identifizierung von „Fallback“-PrognosenIdentifizierung von „Fallback“-Prognosen.',
	RABATTAENDERUNG_FG NUMBER(38,0) COMMENT 'Flag bei Preisänderung des Preisrabattes.',
	ABBILDUNG_VORTAG_ID VARCHAR(6) COMMENT 'Welche Abbildung im Handzettel hatte der Artikel_1 am Vortrag.',
	WERBETHEMA_VORTAG_BEZ VARCHAR(50) COMMENT 'Welches Werbethema hatte der Artikel_1 am Vortag.',
	ART_ID_MUTTER NUMBER(38,0) COMMENT 'Mutter ID zu VK_1-Set/Display Artikeln.',
	WRG_ID VARCHAR(3) COMMENT 'Kurzbezeichnung der Währung, z.B. CZK, EUR.',
	WERBELISTUNG_FG NUMBER(38,0) COMMENT 'Flag zur Anzeige der Werbelistung im PMR (Promotion Management for Retail). Zeigt an ob ein Artikel_1 während der Werbung in dem Markt gelistet ist.\n            Je nach Marktgröße sind die Sortimente verschieden groß, weshalb ein Artikel_1 nach der Werbung wieder ausgelistet sein kann, wenn er nicht zum regulären Sortiment diese Marktes gehört. Bei Artikel_1 die nich regulär in einem Markt gelistet sind, ist die Flag = 0 solange es eine_1 Zwischenaktion vor der betrachteten Aktion_1 gibt, und wird auf 1 gesetzt, sobald die Zwischenaktion vorbei ist.\n            Mit dieser Flag ist es möglich Artikel_1 anzulegen bevor die Werbelistung eintritt, womit eine_1 technische Einschränkung im Quellsystem / SAP überwunden wird, wodurch nur Daten für gelistete Artikel_1 übermittelt wurden. Da ein Artikel_1 für eine_1 zuküftige Aktion_1 in einem Markt vor der Aktion_1 ungelistet sein kann (wenn nicht im regulären Sortiment), und auch keine Werbelistung bestehen kann weil eine_1 Zischenaktion stattfindet, konnten vorher keine (groben) Berechnungen und Bestellungen in WBS für solche zuküftigen Aktionen durchgeführt werden.',
	WERBELISTUNG_AENDERUNG_FG NUMBER(38,0) COMMENT 'Flag zur Anzeige der Änderung der Werbelistung im PMR (Promotion Management for Retail). Zeigt an ob ein Artikel_1 während der Werbung in dem Markt gelistet ist. (Denormalisierung für Frontend-Optimierung. Die Änderung ließe sich vermutlich auch aus dem Unterschied zwischen den Tagen errechnen.)\n            Wenn WERBELISTUNG_FG (siehe eigener Kommentar) von 0 auf 1 gesetzt wird, dann wird am selben Tag_1 auch diese Flag auf 1 gesetzt, und am darauf folgenden Tag_1 wieder auf 0. Die betrachtete Flag kennzeichnet das Datum ab dem genauere Nachberechnungen mit Hilfe von WBS durchgeführt werden können. Eventuell können sich daraus Änderungen an den Bestellmengen ergeben da ab hier eine_1 andere Basis herangezogen werden kann.',
	AKTION_REIHENFOLGE_AENDERUNG_FG NUMBER(38,0) COMMENT 'Flag: Zeigt an, dass zu einem bestimmten DAT_BELADUNG die Aktionsreihenfolge sich geändert hat. Ist für den User hilfreich um nach Änderungen zu filtern.',
	VORTAG_AKTION_REIHENFOLGE_ZUKUNFT_NR NUMBER(38,0) COMMENT 'Gibt an, an wievielter Stelle die betrachtete Aktion_1 am Vortag in der aktuellen Reihenfolge kommender Aktionen steht. ',
	ZEITPUNKT_BESTELLUNG_LIEFERANT_PROGNOSE_BEDARF_BME NUMBER(38,3) COMMENT 'Prognostizierter Bedarf in Basismengeneinheit zum Zeitpunkt der Bestellung beim Lieferanten. Redundant gespeichert zum Wert in BEDARF_BME zu dem Datum als die Bestellung getätigt wurde. Die tatsächliche Bestellmenge kann entweder die volle Bedarfsmenge hier gewesen sein oder die Bedarfsmenge abzüglich des am Datum der Bestellung prognostizierten Bestands zu Werbebeginn im Markt (auch die Prognosen ändern sich über die Zeit_1).',
	WUP_ID_REF NUMBER(38,0) COMMENT 'Der Referenzmarkt, der fuer den Artikelvergleich gespeichert wird. Fuer eine_1 zukuenftige Aktion_1 eines Artikels in einem Markt werden Liefer- und Abverkaufsdaten einer vergangenen Aktion_1 und dem Referenzartikel und -markt herangezogen. Muss nicht gleich sein zu Artikel_1 und Markt der geplanten Aktion_1 sein. Der Referenztyp sagt aus um welche Art_1 von Vergleich es sich handelt.\n            Fuer WBS_ART_WUP_REF_TYP_ID = [2,3,4] kommt es aus der Tabelle ART_WUP_STATUS_REFERENZ_1, welche manuell von Nutzern gepflegt.\n            Fuer den Fall, dass WBS_ART_WUP_REF_TYP_ID = 1 werden die Werte aus Tabelle WBS_ART_AKTION_PER_1 eingefuegt: ART_ID_REF = ART_ID, WUP_ID_REF = WUP_ID und NB_ID_REF = NB_ID sowie FAKTOR_REF = 1.',
	NB_ID_REF NUMBER(38,0) COMMENT 'NB_ID_REF, welche zur WUP_ID_REF gehört.',
	ART_ID_REF NUMBER(38,0) COMMENT 'Der Referenzartikel, der für den Artikelvergleich gespeichert wurde. Fuer eine_1 zukuenftige Aktion_1 eines Artikels in einem Markt werden Liefer- und Abverkaufsdaten einer vergangenen Aktion_1 und dem Referenzartikel und -markt herangezogen. Muss nicht gleich sein zu Artikel_1 und Markt der geplanten Aktion_1 sein. Der Referenztyp sagt aus um welche Art_1 von Vergleich es sich handelt.\n            Fuer WBS_ART_WUP_REF_TYP_ID = [2,3,4] kommt es aus der Tabelle ART_WUP_STATUS_REFERENZ_1, welche manuell von Nutzern gepflegt.\n            Fuer den Fall, dass WBS_ART_WUP_REF_TYP_ID = 1 werden die Werte aus Tabelle WBS_ART_AKTION_PER_1 eingefuegt: ART_ID_REF = ART_ID, WUP_ID_REF = WUP_ID und NB_ID_REF = NB_ID sowie FAKTOR_REF = 1.',
	FAKTOR_REF NUMBER(38,2) COMMENT 'Faktor für die Gewichtung der Referenzmetriken.\n            Fuer WBS_ART_WUP_REF_TYP_ID = [2,3,4] kommt es aus der Tabelle ART_WUP_STATUS_REFERENZ_1, welche manuell von Nutzern gepflegt.\n            Fuer den Fall, dass WBS_ART_WUP_REF_TYP_ID = 1 werden die Werte aus Tabelle WBS_ART_AKTION_PER_1 eingefuegt: ART_ID_REF = ART_ID, WUP_ID_REF = WUP_ID und NB_ID_REF = NB_ID sowie FAKTOR_REF = 1.',
	WFL_MENGE_GEPRUEFT_FG NUMBER(38,0) COMMENT 'Warenfluss_menge_Flag oder Supply chain Managment flag , die der Benutzer setzen kann in der Tabelle (MENGENAENDERUNGEN_WRITEBACK), um zu markieren, dass er die Mengen für diesen Artkel bereits überprüft hat, und würde die beibhalten solange es keine Änderungen bei der Promotion gibt ',
	WFL_MENGE_GEPRUEFT_RESET_FG NUMBER(38,0) COMMENT 'Flag, welches auf 1 gesetzt werden soll, wenn das WFL_MENGE_GEPRUEFT_FG \""resettet\"" wird d.h von 1 auf 0 springt.',
	WFL_NUTZER_KOMMENTAR_TXT VARCHAR(100) COMMENT 'Frei-Text-Feld für den Benutzer\n            Dieses Feld dient dazu, einen zusätzlichen Kommentar zu einem Artikel_1 hinzuzufügen. um besser nachzuvollziehen, was das Problem vorher war',
	FIXMENGE_EK_AENDERUNG_FG NUMBER(38,0) COMMENT 'Bezieht sich auf die  Einkauf FIXMenge Änderung , die in der Spalte Festmenge_BME stattfindet . Das Flag wird auf 1 gesetzt, wenn sich die vom Einkauf gesetzte Fixmenge im Vergleich zum letzten Berechnungstag geändert hat.',
	FIXMENGE_EK_VORTAG_BME NUMBER(38,3) COMMENT 'Diese Spalte ermöglicht dem Benutzer zu erfahren, welche Menge in BME der Einkauf am Vortag hatte. Sie ist auch ist erforderlich, um die Änderung der Fixmenge EK nachzuvollziehen (Spalte: fixmenge_bme). ',
	ANZ_ANGEBOTE_ZEITRAUM NUMBER(38,0) COMMENT 'Anzahl der Angebote, welche die Artikel_markt Kombination und im gleichen Zeitraum stattfinden (art_id, wup_id, dat_von, dat_bis  for the current dat_beladung).',
	ANZ_ANGEBOTE_ZEITRAUM_AENDERUNG_FG NUMBER(38,0) COMMENT 'Flag, welche anzeigt, ob sich die Anzahl der Angebote, die die Artikel_1-Markt-Kombination aufweisen und im selben Zeitraum stattfinden, im Vergleich zum letzten Berechnungstag geändert hat.',
	NUR_ONLINE_FG NUMBER(38,0) COMMENT 'Flag, welches anzeigt, ob die Werbung nur online geschaltet wurde.',
	KUNDENKARTE_PERSONALISIERT_FG NUMBER(38,0) COMMENT 'Flag: welches anzeigt ob die werbung einen personalisierter Kundenkarten-Coupon ist',
	WERBEAENDERUNG_KUNDENKARTE_PERSONALISIERT_FG NUMBER(38,0) COMMENT 'Flag, welches anzeigt, ob eine_1 Änderung in dem KUNDENKARTE_PERSONALISIERT Coupons im Vergleich zum letzten Tag_1 erfolgte',
	STILLE_AKTION_MIT_MENGE_FG NUMBER(38,0) COMMENT 'Flag, welches anzeigt, dass die Werbung eine_1 stille Werbung ist, die nur in Filialen beworben ist, aber mit Menge_hochrechnung.( für Kombination WERBEMITTEL_ART_ID = 0920 & WERBEMITTEL_ID = 50)',
	MIN_PLATZIERUNG_MARKT_CLUSTER_ID NUMBER(38,0) COMMENT 'Markt-Cluster für Mindestplatzierung (1-3).',
	ESTIMATION_ID NUMBER(38,0) COMMENT 'With this ID the user can decide in which way the estimation for WBS TP2 should be calculated.\n            ID 0 = no estimation\n            ID 1 = calculate normal estimation process\n            ID 2 = only fill up maximum capacity (Berechnung für die Werbung in WBS, aber nur um das Regal aufzufüllen)',
	ESTIMATION_ID_AENDERUNG_FG NUMBER(38,0) COMMENT 'Flag zur Anzeige der Änderung der Estimation-ID im Vergleich zum Vortag (1 oder 0). Ist für den User hilfreich um nach Änderungen zu filtern.',
	UTP_RELEVANT_FG NUMBER(38,0) COMMENT 'Gibt an ob einen Artikel_1 als UTP-relevant markiert ist (0 oder 1).\n            UTP = Unfair trade practices. Ist ein EU-Gesetz um kleine Lieferanten vor Großaufträgen zu schützen.',
	UTP_RELEVANT_AENDERUNG_FG NUMBER(38,0) COMMENT 'Flag zeigt die Änderung der UTP_RELEVANT_FG im Vergleich zum Vortag (1 oder 0). Ist für den User hilfreich um nach Änderungen zu filtern.',
	UTP_LIEFERANT_BESTAETIGT_FG NUMBER(38,0) COMMENT 'Flag gibt an, ob ein UTP-Lieferant die Werbebestellmenge freigegeben hat (0 oder 1).',
	DAT_GUELTIG_VON_KONDITIONSART_ZAR5 DATE COMMENT 'Beginn der Gültigkeit der Konditionsart ZAR5.',
	DAT_GUELTIG_BIS_KONDITIONSART_ZAR5 DATE COMMENT 'Ende der Gültigkeit der Konditionsart ZAR5.',
	MENGE_KOLLIINHALT_VORTAG_BME NUMBER(38,3) COMMENT 'Kolliinhalt des Vortages. Aus Feld: Kollifaktor (Menge in BME pro Kolli).',
	INIT_LIEF_MODUS_KZ VARCHAR(100) COMMENT 'Beschreibt den Modus, in welchem die initiale Belieferung berechnet wird (O = Order, S = Simulation, N = None).\n            - N: wenn keine initiale Belieferung errechnet wird (vor wbs_phase_id = 8).\n            - S: berechnen die Erstlieferung 40 Tage vor der Promotion - es werden keine wirklichen Bestellungen in den Geschäften erzeugt sondern die Spalte ermöglicht DC Dispo, den ersten Liefersplit schon sehr früh zu sehen und die Mengen beim Lieferanten entsprechend zu bestellen (wbs_phase_id 7 bis 3).\n            - O: der ursprüngliche initiale Lieferlauf findet 9 Tage vor der Promotion statt, und der Berechnungslauf wird als \""O\"" (Order Creation) gekennzeichnet (ab wbs_phase_id = 2).',
	GP_ID_AENDERUNG_FG NUMBER(38,0) COMMENT 'Flag, welches angibt, ob sich die Lieferantennummer (GP_ID) geändert hat',
	KONDITIONSART_ZAR5_GUELTIGKEIT_AENDERUNG_FG NUMBER(38,0) COMMENT 'Flag, welches angibt, ob sich der Zeitraum für die ZAR5-Gültigkeit geändert hat.',
	POSTEN_KZ_SAP VARCHAR(2) COLLATE 'en-ci' COMMENT 'Postenkennzeichen. Für Artikel_1, die nicht ständig im Sortiment sind (Unterschied zur posten_id: für KMO werden die tatsächlichen Werte aus SAP gespeichert)',
	POSTEN_KZ_SAP_AENDERUNG_FG NUMBER(38,0) COMMENT 'Flag, welches angibt, ob der Artikel_1 von Posten auf Sortimentsartikel oder umgekehrt geändert hat',
	BONUSKAUF_PROMOTIONSTYP_LISTE_TXT VARCHAR(1000) COMMENT 'Die Spalte enthält die konkatenierten Aktionsarten (Feld AKART in PMR), erwartete Einträge sind z.B. 0001, 0005, ZAI, ZBBR.\n            Gibt die Aktionsart für eine_1 Aktion_ID an Z.B:\n            Aktionsart ''0001'' eine_1 Standard-Aktion_1 im Prospekt\n            oder ''ZBBR'' wäre_1 eine_1 Bonuskauf-Aktion.\n            Die Art_1 der Aktion_1 hat Einfluss darauf, ob und wie die SCM-Mengen für diese Aktion_1 berechnet werden.',
	SAISON_ID VARCHAR(10) COLLATE 'en-ci' COMMENT 'ID der Saison aus saiso, z.Bsp 9.',
	SAISON_ID_AENDERUNG_FG NUMBER(38,0) COMMENT 'Flag, gibt an, ob der Artikel_1 das Saisonkennzeichen geändert hat',
	BEST_MENGE_EINH_ID VARCHAR(3) COLLATE 'en-ci' COMMENT 'Bestellmengeneinheit. Diese Mengeneinheit wird standardmäßig bei Bestellungen verwendet.',
	BEST_MENGE_EINH_VORTAG_ID VARCHAR(3) COMMENT 'Bestellmengeneinheit des Vortages. Diese Mengeneinheit wird standardmäßig bei Bestellungen verwendet.',
	BEST_MENGE_EINH_ID_AENDERUNG_FG NUMBER(38,0) COMMENT 'Flag, gibt an, ob es eine_1 Änderung der Bestellmengeneinheit zum Vortag gab',
	BEDARF_ESTIMATION_ID_2_BME NUMBER(18,3) COMMENT 'Simulierter Bedarf in Basismengeneinheit, welcher unter Verwendung der Estimation_ID = 2 ermittelt werden würde.',
	BESTELLMENGE_ESTIMATION_ID_2_OHNE_BESTAND_AME NUMBER(38,3) COMMENT 'Simulierte Werbe-Bestellmenge ohne Bestandsberücksichtigung in Ausliefermengeneinheit (AME, z.B. Kolli oder KG), welcher unter Verwendung der Estimation_ID = 2 ermittelt werden würde.',
	BESTELLMENGE_ESTIMATION_ID_2_MIT_BESTAND_AME NUMBER(38,3) COMMENT 'Simulierte Werbe-Bestellmenge mit Bestandsberücksichtigung in Ausliefermengeneinheit (AME, z.B. Kolli oder KG), welcher unter Verwendung der Estimation_ID = 2 ermittelt werden würde.',
	ADJUSTMENT_ID NUMBER(38,0) COMMENT 'Mit der Adjustment_ID kann der Benutzer entscheiden, auf welche Weise die Nachversorgung in WBS TP1 berechnet werden soll.\n            0 = UDF&R: UDF berechnet die Prognosen und übergibt sie an F&R\n            1 = Standard adjustment (WBS): WBS berechnet die Nachversorgungsmenge und stellt sie den Benutzern als PREX-Upload zur Verfügung.\n            2 = Platzhalter (Stand 28.03.2025)\n            3 = External adjustment: Die SAP Autodispo errechnet keine Mengen. In diesem Fall ist eine_1 manuelle Bestellanlage durch das Land_1 notwendig.',
	TD_UPDATE TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	TD_INSERT TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	BONUSKAUF_PROMOTIONSTYP_LISTE_VORTAG_TXT VARCHAR(1000) COMMENT 'Die Spalte enthält die konkatenierten Aktionsarten des vorangegangenen Berechnungslaufs. \n            Struktur und Logik entsprechen der Spalte BONUSKAUF_PROMOTIONSTYP_LISTE_TXT, jedoch mit dem Stand des Vorlaufs.',
	DK_FG NUMBER(38,0) COMMENT 'Flag gibt an, ob eine_1 Aktion_1 (Offer) in der UDF-Prognose durch die sogenannte Doorkeeper-Logik herausgefiltert wurde.\n            1 (Ja): Die Aktion_1 wurde durch den Doorkeeper ausgefiltert und ist somit in UDF inaktiv.\n            0 (Nein): Die Aktion_1 wurde nicht ausgefiltert und bleibt in UDF aktiv.\n            Quelle ist das Feld DK_RELEVANCE aus der SAP Tabelle ZUDF_OFRWBS_DATA. Mapping: wenn X=1, sonst 0.',
	constraint PK_WBS_WERBEAENDERUNGEN primary key (MANDANT_ID, AKTION_ID, OFFER_ID, WUP_ID, ART_ID, DAT_BELADUNG, MANDANT_ID_VZ, WUP_ID_VZ)
)COMMENT='SCM-WBS - Werbeänderungen (kumuliert).'
;
